import re
acts=[]
for ln in lines:
 d=json.loads(ln); m=d.get('message',{}); cont=m.get('content',[])
 if isinstance(cont,list):
  txt=''.join(x.get('text','') for x in cont if isinstance(x,dict))
  if '"action": "submit"' in txt or '"action":"submit"' in txt:
   # extract from action onwards
   mt=re.search(r'\{\s*"action"\s*:\s*"submit".*\}\s*$',txt,re.S)
   if mt:
    try: acts.append(json.loads(mt.group()))
    except Exception as e: print('err',e,mt.group()[-100:])
len(acts),[(len(a['grid']), set(map(len,a['grid']))) for a in acts]

